void test_c_td_comp(Rng &rng, Report &report) {
  for (int iter = 0; iter < kIterations; ++iter) {
    Operand<td_tag> a(random_qd(rng, Domain::any));
    Operand<td_tag> b = near_operand<td_tag>(ref_of(a), iter);
    int result = 2;
    c_td_comp(a.limbs, b.limbs, &result);
    const qd_real diff = ref_of(a) - ref_of(b);
    const int expected = diff < 0.0 ? -1 : (diff > 0.0 ? 1 : 0);
    report.check("c_td_comp", result == expected);
  }
}
