void test_c_qd_rand(Rng &rng, Report &report) {
  for (int iter = 0; iter < kIterations; ++iter) {
    if (iter == 0) {
      Operand<qd_tag> a;
      double lo = 1.0, hi = 0.0, sum = 0.0;
      bool in_range = true;
      for (int i = 0; i < 4000; ++i) {
        c_qd_rand(a.limbs);
        const qd_real v = a.value();
        in_range = in_range && v >= 0.0 && v < 1.0;
        lo = std::min(lo, to_double(v));
        hi = std::max(hi, to_double(v));
        sum += to_double(v);
      }
      report.check("c_qd_rand in [0, 1)", in_range);
      report.check("c_qd_rand range", lo < 0.01 && hi > 0.99);
      report.check("c_qd_rand mean", std::fabs(sum / 4000 - 0.5) < 0.02);
      Operand<qd_tag> b;
      qd_srand(77);
      c_qd_rand(a.limbs);
      qd_srand(77);
      c_qd_rand(b.limbs);
      report.check("c_qd_rand reproducible", a.value() == b.value());
    }
  }
}
void test_c_qd_comp(Rng &rng, Report &report) {
  for (int iter = 0; iter < kIterations; ++iter) {
    Operand<qd_tag> a(random_qd(rng, Domain::any));
    Operand<qd_tag> b = near_operand<qd_tag>(ref_of(a), iter);
    int result = 2;
    c_qd_comp(a.limbs, b.limbs, &result);
    const qd_real diff = ref_of(a) - ref_of(b);
    const int expected = diff < 0.0 ? -1 : (diff > 0.0 ? 1 : 0);
    report.check("c_qd_comp", result == expected);
  }
}
